-- pandora-primitive: pandora-billing@1.0.0
-- target: customer-app-runtime-only
DO $$ BEGIN IF to_regclass('public.project_specs') IS NOT NULL OR to_regclass('public.projectos_execution_plans') IS NOT NULL OR to_regclass('public.pandora_projects') IS NOT NULL THEN RAISE EXCEPTION 'pandora-billing customer primitive refused on Pandora Control Plane-like schema'; END IF; END $$;
CREATE TABLE IF NOT EXISTS public.primitive_payment_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scope_id uuid NOT NULL,provider text NOT NULL,provider_payment_id text NOT NULL,status text NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>=0),currency text NOT NULL CHECK(currency~'^[A-Z]{3}$'),order_id uuid,idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(scope_id,provider,provider_payment_id),UNIQUE(scope_id,idempotency_key));
CREATE TABLE IF NOT EXISTS public.primitive_payment_webhook_events(provider text NOT NULL,provider_event_id text NOT NULL,payload_digest text NOT NULL CHECK(payload_digest~'^sha256:[a-f0-9]{64}$'),processed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(provider,provider_event_id));
ALTER TABLE public.primitive_payment_records ENABLE ROW LEVEL SECURITY;ALTER TABLE public.primitive_payment_records FORCE ROW LEVEL SECURITY;ALTER TABLE public.primitive_payment_webhook_events ENABLE ROW LEVEL SECURITY;ALTER TABLE public.primitive_payment_webhook_events FORCE ROW LEVEL SECURITY;REVOKE ALL ON public.primitive_payment_records,public.primitive_payment_webhook_events FROM anon,authenticated;
-- Payment mutation and webhook tables are server/provider-adapter only. No client write/read grant is installed by default.
